package org.skdocs.skdocstool.docs;

import ch.njol.skript.doc.*;
import ch.njol.skript.lang.function.Function;
import org.skriptlang.skript.common.function.DefaultFunction;
import ch.njol.skript.classes.ClassInfo;
import org.bukkit.event.Cancellable;
import org.bukkit.event.Event;
import org.skriptlang.skript.bukkit.lang.eventvalue.EventValue;
import org.skriptlang.skript.bukkit.lang.eventvalue.EventValueRegistry;
import org.skriptlang.skript.bukkit.registration.BukkitSyntaxInfos;
import org.skriptlang.skript.common.function.Parameter;
import org.skriptlang.skript.common.function.Parameters;
import org.skriptlang.skript.registration.DefaultSyntaxInfos;
import org.skriptlang.skript.registration.SyntaxInfo;

import java.util.*;
import java.util.stream.Collectors;

public class CleanSyntax {

	public static SyntaxData fromSyntaxInfo(SyntaxInfo<?> syntax) {
		Class<?> clazz = syntax.type();
		if (clazz != null && clazz.isAnnotationPresent(NoDoc.class)) return null;

		SyntaxData data = new SyntaxData();
		String[] rawPatterns = syntax.patterns().toArray(new String[0]);
		data.patterns = cleanSyntaxPatterns(rawPatterns, false);

		data.name = ann(clazz, Name.class) != null
				? clazz.getAnnotation(Name.class).value()
				: generateCleanName(data.patterns.length > 0 ? data.patterns[0] : null);

		data.id = ann(clazz, DocumentationId.class) != null
				? clazz.getAnnotation(DocumentationId.class).value()
				: (clazz != null ? clazz.getSimpleName() : toId(data.name));

		data.description = annValues(clazz, Description.class);
		data.since        = annSince(clazz);
		data.examples     = annExamples(clazz);

		if (syntax instanceof DefaultSyntaxInfos.Expression<?, ?> expr && expr.returnType() != null) {
			data.returnType = expr.returnType().getSimpleName();
		}

		data.addonName = null;
		data.source    = clazz != null ? clazz.getName() : "Unknown";
		return data;
	}

	public static SyntaxData fromEventSyntax(BukkitSyntaxInfos.Event<?> event, EventValueRegistry eventValueRegistry) {
		SyntaxData data = new SyntaxData();
		String[] rawPatterns = event.patterns().toArray(new String[0]);
		data.patterns = cleanSyntaxPatterns(rawPatterns, false);

		data.name = (event.name() != null && !event.name().isBlank())
				? event.name()
				: generateCleanName(data.patterns.length > 0 ? data.patterns[0] : null);

		data.id = (event.documentationId() != null && !event.documentationId().isBlank())
				? event.documentationId()
				: (!event.id().isBlank() ? event.id() : toId(data.name));

		data.description = cleanArray(event.description());
		data.examples    = cleanArray(event.examples());
		data.since       = cleanArray(event.since());
		data.cancellable = event.events().stream().anyMatch(Cancellable.class::isAssignableFrom);
		data.addonName   = null;
		data.source      = event.type() != null ? event.type().getName() : "Unknown";

		if (eventValueRegistry != null) {
			data.eventValues = getEventValues(eventValueRegistry, event.events());
		}
		return data;
	}

	public static SyntaxData fromClassInfo(ClassInfo<?> info) {
		SyntaxData data = new SyntaxData();
		data.name        = info.getDocName() != null ? info.getDocName() : info.getName().toString();
		data.id          = "type_" + info.getCodeName();
		data.patterns    = new String[]{info.getCodeName()};
		data.description = toCleanArray(info.getDescription());
		data.since       = toCleanArray(info.getSince());
		data.addonName   = null;
		data.source      = info.getC().getName();
		return data;
	}

	public static SyntaxData fromFunction(Function<?> function) {
		SyntaxData data = new SyntaxData();

		// DefaultFunction implements Documentable — use its API for doc fields
		if (function instanceof Documentable doc) {
			String docName = doc.name();
			data.name        = (docName != null && !docName.isBlank()) ? docName : null;
			data.description = cleanArray(doc.description());
			data.examples    = cleanArray(doc.examples());
			data.since       = cleanArray(doc.since());
		}

		// annotation fallbacks
		Class<?> clazz = function.getClass();
		if (data.name == null) {
			data.name = ann(clazz, Name.class) != null
					? clazz.getAnnotation(Name.class).value()
					: capitalize(function.getName());
		}
		if (data.description == null || data.description.length == 0)
			data.description = annValues(clazz, Description.class);
		if (data.examples == null || data.examples.length == 0)
			data.examples = annExamples(clazz);

		data.id = "fn_" + function.getName().toLowerCase(Locale.ROOT);

		// build signature using new Parameters API
		Parameters params = function.getSignature().parameters();
		StringBuilder sig = new StringBuilder(function.getName()).append("(");
		Parameter<?>[] paramArr = params.all();
		if (paramArr != null) {
			for (int i = 0; i < paramArr.length; i++) {
				Parameter<?> p = paramArr[i];
				ClassInfo<?> typeInfo = ch.njol.skript.registrations.Classes.getExactClassInfo(p.type());
				String typeName = typeInfo != null ? typeInfo.getCodeName() : p.type().getSimpleName().toLowerCase(Locale.ROOT);
				sig.append(p.name()).append(": ").append(typeName);
				if (i < paramArr.length - 1) sig.append(", ");
			}
		}
		sig.append(")");
		data.patterns = new String[]{sig.toString()};

		if (function.getReturnType() != null) data.returnType = function.getReturnType().getCodeName();

		// Use the addon's source class so resolveAddonName() can correctly identify the plugin
		if (function instanceof DefaultFunction<?> df) {
			Class<?> addonSrc = df.source().source();
			data.source = addonSrc != null ? addonSrc.getName() : clazz.getName();
		} else {
			data.source = clazz.getName();
		}
		return data;
	}

	public static String[] cleanSyntaxPatterns(String[] patterns, boolean isFunction) {
		if (patterns == null) return new String[0];
		List<String> result = new ArrayList<>();
		for (String pattern : patterns) {
			if (pattern == null) continue;
			String p = pattern
					.replaceAll("\\d+[¦Â¦]", "")
					.replaceAll("\\\\([()])", "$1")
					.replaceAll("%-(.+?)%", "%$1%")
					.replaceAll("%~(.+?)%", "%$1%")
					.replace("()", "")
					.replaceAll("@-?\\d", "")
					.replaceAll("\\([- ]\\|[- ]\\)", " ")
					.replaceAll("\\s+", " ");
			if (!isFunction) {
				p = p.replaceAll("(\\w+):", "")
						.replace("[:", "[")
						.replace("(:", "(")
						.replace("|:", "|");
			}
			result.add(p.trim());
		}
		return result.toArray(new String[0]);
	}

	public static String cleanString(String input) {
		if (input == null || input.isBlank()) return null;
		return input
				.replaceAll("<[^>]*>", "")
				.replace("&lt;", "<")
				.replace("&gt;", ">")
				.replace("&amp;", "&")
				.trim();
	}

	public static String[] cleanArray(String[] array) {
		if (array == null || array.length == 0) return null;
		List<String> result = Arrays.stream(array)
				.map(CleanSyntax::cleanString)
				.filter(s -> s != null && !s.isBlank())
				.collect(Collectors.toList());
		return result.isEmpty() ? null : result.toArray(new String[0]);
	}

	public static String[] cleanArray(Collection<String> collection) {
		if (collection == null || collection.isEmpty()) return null;
		return cleanArray(collection.toArray(new String[0]));
	}

	public static String generateCleanName(String pattern) {
		if (pattern == null || pattern.isBlank()) return "Unknown";
		String name = pattern
				.replaceAll("%[^%]+%", " ")
				.replaceAll("[^a-zA-Z0-9\\s]", " ")
				.replaceAll("\\s+", " ")
				.trim();
		if (name.isBlank()) return "Unknown";
		StringBuilder sb = new StringBuilder();
		for (String word : name.split(" ")) {
			if (word.isBlank()) continue;
			if (!sb.isEmpty()) sb.append(' ');
			sb.append(Character.toUpperCase(word.charAt(0))).append(word.substring(1).toLowerCase(Locale.ROOT));
		}
		String result = sb.toString().trim();
		return result.isBlank() ? "Unknown" : result;
	}

	private static String[] getEventValues(EventValueRegistry registry, Collection<Class<? extends Event>> events) {
		if (events == null || events.isEmpty()) return null;
		List<EventValue<?, ?>> allValues = registry.elements();
		LinkedHashSet<String> values = new LinkedHashSet<>();

		for (EventValue<?, ?> ev : allValues) {
			boolean matches = events.stream().anyMatch(e ->
					e.isAssignableFrom(ev.eventClass()) || ev.eventClass().isAssignableFrom(e));
			if (!matches) continue;

			String prefix = switch (ev.time()) {
				case PAST -> "past ";
				case FUTURE -> "future ";
				default -> "";
			};

			String[] patterns = ev.patterns();
			if (patterns != null && patterns.length > 0) {
				for (String p : patterns) {
					if (p != null && !p.isBlank()) values.add(prefix + p.trim());
				}
			} else {
				values.add(prefix + "event-" + ev.valueClass().getSimpleName().toLowerCase(Locale.ROOT));
			}
		}

		LinkedHashSet<String> cleaned = new LinkedHashSet<>();
		for (String v : values) cleaned.add(v.replace("[]", ""));
		return cleaned.isEmpty() ? null : cleaned.toArray(new String[0]);
	}

	private static <A extends java.lang.annotation.Annotation> A ann(Class<?> clazz, Class<A> type) {
		if (clazz == null || !clazz.isAnnotationPresent(type)) return null;
		return clazz.getAnnotation(type);
	}

	private static String[] annValues(Class<?> clazz, Class<? extends java.lang.annotation.Annotation> type) {
		if (clazz == null || !clazz.isAnnotationPresent(type)) return null;
		try {
			Object value = type.getMethod("value").invoke(clazz.getAnnotation(type));
			String[] arr = value instanceof String[] ? (String[]) value : new String[]{(String) value};
			return cleanArray(arr);
		} catch (Exception e) {
			return null;
		}
	}

	private static String[] annSince(Class<?> clazz) {
		Since since = ann(clazz, Since.class);
		if (since == null) return null;
		return cleanArray(since.value());
	}

	private static String[] annExamples(Class<?> clazz) {
		if (clazz == null) return null;
		if (clazz.isAnnotationPresent(Examples.class))
			return cleanArray(clazz.getAnnotation(Examples.class).value());
		if (clazz.isAnnotationPresent(Example.class))
			return cleanArray(new String[]{clazz.getAnnotation(Example.class).value()});
		return null;
	}

	private static String[] toCleanArray(Object obj) {
		if (obj == null) return null;
		if (obj instanceof String[] arr) return cleanArray(arr);
		return cleanArray(new String[]{String.valueOf(obj)});
	}

	private static String toId(String input) {
		if (input == null || input.isBlank()) return "unknown_syntax";
		return input.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+", "_").replaceAll("^_+|_+$", "");
	}

	private static String capitalize(String input) {
		if (input == null || input.isBlank()) return input;
		return Character.toUpperCase(input.charAt(0)) + input.substring(1).toLowerCase(Locale.ROOT);
	}
}

