package org.skdocs.skdocstool.docs;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.util.Map;

public class SkriptDocsJsonFile {

    public JsonObject build(String addonName, Map<String, Map<String, SyntaxData>> categories) {
        JsonObject root = new JsonObject();

        // Source info
        JsonObject source = new JsonObject();
        source.addProperty("name", addonName);
        root.add("source", source);

        // Each category is an array of syntax entries
        for (Map.Entry<String, Map<String, SyntaxData>> category : categories.entrySet()) {
            if (category.getValue().isEmpty()) continue;
            JsonArray categoryArray = new JsonArray();
            for (SyntaxData syntax : category.getValue().values()) {
                categoryArray.add(syntax.toAddonEntryJson());
            }
            if (categoryArray.size() > 0) {
                root.add(category.getKey(), categoryArray);
            }
        }

        return root;
    }
}

package org.skdocs.skdocstool.docs;

import com.google.gson.JsonObject;
import java.util.Map;

public class SkriptDocsJsonFile {
    public JsonObject build(String addonName, Map<String, Map<String, SyntaxData>> categories) {
        JsonObject addonObject = new JsonObject();
        JsonObject addonContent = new JsonObject();
        for (Map.Entry<String, Map<String, SyntaxData>> category : categories.entrySet()) {
            if (category.getValue().isEmpty()) continue;
            JsonObject categoryObject = new JsonObject();
            for (Map.Entry<String, SyntaxData> syntax : category.getValue().entrySet()) {
                categoryObject.add(syntax.getKey(), syntax.getValue().toAddonEntryJson());
            }
            if (categoryObject.size() > 0) addonContent.add(category.getKey(), categoryObject);
        }
        addonObject.add(addonName, addonContent);
        return addonObject;
    }
}

package org.skdocs.skdocstool.docs;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.google.gson.JsonPrimitive;

public class SyntaxData {
    public String id;
    public String name;
    public String[] patterns;
    public String[] description;
    public String[] since;
    public String[] examples;
    public String returnType;
    public String addonName;
    public String source;
    public boolean cancellable;
    public String[] eventValues;

    public JsonObject toAddonEntryJson() {
        JsonObject jsonObject = new JsonObject();
        jsonObject.addProperty("id", id);
        jsonObject.addProperty("name", name);

        JsonArray patternsArray = new JsonArray();
        if (patterns != null) {
            for (String pattern : patterns) patternsArray.add(new JsonPrimitive(pattern));
        }
        jsonObject.add("syntax", patternsArray);

        jsonObject.add("description", convertStringArrayToJson(description));
        jsonObject.add("since", convertStringArrayToJson(since));
        jsonObject.add("examples", convertStringArrayToJson(examples));

        jsonObject.addProperty("source", source);
        jsonObject.addProperty("addon", addonName);

        if (returnType != null) {
            jsonObject.addProperty("return_type", returnType);
        }

        if (eventValues != null && eventValues.length > 0) {
            jsonObject.add("event_values", convertStringArrayToJson(eventValues));
        }

        return jsonObject;
    }

    private JsonArray convertStringArrayToJson(String[] array) {
        JsonArray jsonArray = new JsonArray();
        if (array != null) {
            for (String item : array) jsonArray.add(new JsonPrimitive(item));
        }
        return jsonArray;
    }
}

package org.skdocs.skdocstool.docs;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.google.gson.JsonPrimitive;

public class SyntaxData {
    public String id;
    public String name;
    public String[] patterns;
    public String[] description;
    public String[] since;
    public String[] examples;
    public String returnType;
    public String addonName;
    public String source;   // SyntaxInfo.type().getName() — the implementation class
    public String origin;   // SyntaxInfo.origin().name() — the declared origin/addon
    public boolean cancellable;
    public String[] eventValues;

    public JsonObject toAddonEntryJson() {
        JsonObject jsonObject = new JsonObject();
        jsonObject.addProperty("id", id);
        jsonObject.addProperty("name", name);

        JsonArray patternsArray = new JsonArray();
        if (patterns != null) {
            for (String pattern : patterns) patternsArray.add(new JsonPrimitive(pattern));
        }
        jsonObject.add("syntax", patternsArray);

        jsonObject.add("description", convertStringArrayToJson(description));
        jsonObject.add("since", convertStringArrayToJson(since));
        jsonObject.add("examples", convertStringArrayToJson(examples));

        jsonObject.addProperty("source", source);
        jsonObject.addProperty("origin", origin);
        jsonObject.addProperty("addon", addonName);

        if (returnType != null) {
            jsonObject.addProperty("return_type", returnType);
        }

        if (eventValues != null && eventValues.length > 0) {
            jsonObject.add("event_values", convertStringArrayToJson(eventValues));
        }

        return jsonObject;
    }

    private JsonArray convertStringArrayToJson(String[] array) {
        JsonArray jsonArray = new JsonArray();
        if (array != null) {
            for (String item : array) jsonArray.add(new JsonPrimitive(item));
        }
        return jsonArray;
    }
}

